using System.Collections.Generic; using Crownfall.Battle.Combat; using Crownfall.Core; using Crownfall.Units; using UnityEngine;
namespace Crownfall.StatusEffects { public sealed class StatusContainer { sealed class I{public StatusDefinition d;public Unit s;public int n;public float left,tick;public I(StatusDefinition d,Unit s,int n){this.d=d;this.s=s;this.n=n;left=d.duration;tick=d.tickInterval;}} readonly Unit owner; readonly List<I> list=new(); public StatusContainer(Unit o){owner=o;} public bool Has(StatusType t){foreach(var x in list)if(x.d.type==t)return true;return false;} public int Stacks(StatusType t){int n=0;foreach(var x in list)if(x.d.type==t)n+=x.n;return n;} public void Apply(StatusDefinition d,Unit source,int stacks=1){if(d==null)return;I found=list.Find(x=>x.d==d);if(found==null||d.stackRule==StatusStackRule.Independent){list.Add(new I(d,source,Mathf.Clamp(stacks,1,d.maxStacks)));return;} if(d.stackRule==StatusStackRule.Ignore)return;if(d.stackRule==StatusStackRule.StackIntensity)found.n=Mathf.Min(d.maxStacks,found.n+stacks);else if(d.stackRule==StatusStackRule.Replace)found.n=Mathf.Clamp(stacks,1,d.maxStacks); found.left=d.stackRule==StatusStackRule.StackDuration?found.left+d.duration:d.duration;}
 public void Tick(BattleClock clock,DamageSystem damage){if(clock==null||clock.DeltaTime<=0)return;for(int i=list.Count-1;i>=0;i--){var x=list[i];x.left-=clock.DeltaTime;if(x.d.periodic){x.tick-=clock.DeltaTime;while(x.tick<=0&&x.left>0){x.tick+=x.d.tickInterval;float raw=(x.d.flatDamage+(x.s==null?0:x.s.Definition.attack*x.d.sourceAttackScaling))*x.n;damage.Apply(x.s,owner,raw,DamageType.True,false);}}if(x.left<=0)list.RemoveAt(i);}} public void Clear()=>list.Clear(); } }
